    "他把“明星”活成了责任：扛球权、扛防守、扛更衣室的情绪，也扛整座城市的期待。{星光}，{生涯体量}。他的星光不是聚光灯给的，是自己一点点挣来的。",
    "他是那种能让队友变好的球星，也是那种能让对手服气的对手。{星光}之外，他更愿意谈球队、谈过程、谈那些没人看见的加练。他的伟大里有分寸，也有骄傲。",
    "每个赛季开始前，人们都会列出他的挑战者；每个赛季结束，人们发现他还在那里。{星光}，{球队线}。他的生涯证明了一件事：真正的超级球星，是用时间反复确认的。",
    "他把数据打成了日常，把日常打成了习惯，把习惯打成了风格。{星光}，场均{场均得分}分、场均{场均篮板}个篮板，这些数字放在一起，就是他留给联盟的签名。",
