function buildCareerEvaluationScores() {
  var c = STATE.career || {};
  var honors = c.honors || [];
  var ts = c.totalStats || {};
  var tg = Math.max(ts.games || 0, 1);
  var avgPts = (ts.pts || 0) / tg;
  var avgAst = (ts.ast || 0) / tg;
  var avgStl = (ts.stl || 0) / tg;
  var avgBlk = (ts.blk || 0) / tg;
  function cnt(key) { return honors.filter(function(h) { return (h.label || '').indexOf(key) >= 0; }).length; }
  var championships = cnt('总冠军');
  var mvp = honors.filter(function(h) { return (h.label || '') === 'MVP'; }).length;
  var fmvp = cnt('总决赛MVP') + cnt('FMVP');
  var allNBA = cnt('最佳阵容');
  var allStar = cnt('全明星');
  var dpoy = cnt('DPOY');
  var roty = cnt('最佳新秀');
  var teams = [];
  var teamYears = {};
  (c.seasons || []).forEach(function(se) {
    if (teams.indexOf(se.team) < 0) teams.push(se.team);
    teamYears[se.team] = (teamYears[se.team] || 0) + 1;
  });
  var longest = 0;
  Object.keys(teamYears).forEach(function(t) { if (teamYears[t] > longest) longest = teamYears[t]; });
  var flags = c.flags || {};
  var profile = c.profile || {};
  var legacy = c.legacy || {};
  var scores = { ordinary: 1 };
  function add(key, n) { scores[key] = (scores[key] || 0) + (n || 1); }
  if (championships >= 3) add('champion', 9 + championships * 2);
  else if (championships === 2) add('champion', 7);
  else if (championships === 1) add('champion', 5);
  if (mvp >= 2) add('star', 8 + mvp * 2 + allNBA);
  else if (mvp === 1) add('star', 5);
  else if (allNBA + allStar >= 8) add('star', 4);
  if (avgPts >= 27) add('scorer', 7);
  else if (avgPts >= 23) add('scorer', 4);
  if (avgAst >= 8) add('playmaker', 6);
  else if (avgAst >= 5) add('playmaker', 3);
  if (dpoy > 0) add('defender', 6);
  else if (avgStl + avgBlk >= 2.5) add('defender', 3);
  if (ts.games >= 1000) add('durable', 8);
  else if (ts.games >= 800) add('durable', 4);
  if (teams.length === 1 && (c.seasons || []).length >= 8) add('loyalty', 8);
  else if (longest >= 8) add('loyalty', 5);
  else if (longest >= 5) add('loyalty', 2);
  if (teams.length >= 4) add('journey', 5);
  else if (teams.length === 3) add('journey', 3);
  if (!roty && allStar >= 3) add('late', 5);
  if (flags.mentalResilient) add('comeback', 6);
  var cnNode = getBranchNode('china_team');
  if (['national_legend','national_mentor','honorable_exit','national_core','team_core','managed_core','national_flag','team_revival','injured_hero'].indexOf(cnNode) >= 0) add('china', 7);
  if (getBranchNode('china_market') === 'shoe_settled' || (profile.chinaPopularity || 0) >= 8) add('market', 5);
  if (getBranchNode('family') !== 'start' || flags.familyRetireTendency) add('family', 5);
  if (getBranchNode('teammate_bond') !== 'start') add('teammate', 4);
  if (getBranchNode('team_practice') === 'practice_identity' || (profile.lockerRoomTrust || 0) >= 8) add('leader', 5);
  if (getBranchNode('media') !== 'start') add('media', 3);
  if (flags.fanCulturePersona || (profile.fanSupport || 0) >= 8) add('fan', 4);
  if (flags.legacyHurt || flags.finalHurt) add('injury', 5);
  if (flags.postCareerIdentity) add('postcareer', 4);
  if (flags.cityLoyal || flags.cityIcon || flags.cityAcademy || flags.cityParade) add('city', 5);
  if (flags.mentalResilient) add('mental', 3);
  if (legacy.goat || legacy.hof || legacy.top100 || legacy.tier === '历史前十级别') add('legacy', 6);
  if ((profile.controversy || 0) >= 5) add('controversy', 4);
  if ((c.seasons || []).length >= 10) add('durable', 2);
  return scores;
}

