function biographySeed(str) {
  var h = 2166136261;
  str = String(str || 'buildplayer');
  for (var i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function biographyPick(list, seed, salt) {
  if (!list || !list.length) return '';
  return list[(seed + salt * 2654435761) % list.length];
}

