expandCareerBiographyCopyBank();

function countCareerBiographyCopyBank() {
  var total = 0;
  var bySection = {};
  Object.keys(CAREER_BIOGRAPHY_RULED_COPY).forEach(function(section) {
    bySection[section] = (CAREER_BIOGRAPHY_RULED_COPY[section] || []).length;
    total += bySection[section];
  });
  return { total: total, sections: bySection };
}

function biographyHasTag(tags, tag) {
  return (tags || []).indexOf(tag) >= 0;
}

function biographyEntryScore(entry, tags) {
  if (typeof entry === 'string') return 1;
  var score = 0;
  var entryTags = entry.tags || [];
  if (biographyHasTag(entryTags, 'late_peak') && !biographyHasTag(tags, 'late_peak')) return -999;
  if (biographyHasTag(entryTags, 'late_career_gift') && !biographyHasTag(tags, 'late_career_gift')) return -999;
  if (biographyHasTag(entryTags, 'late_champion') && !biographyHasTag(tags, 'late_champion')) return -999;
  if (biographyHasTag(entryTags, 'late_peak') && biographyHasTag(entryTags, 'champion') && !biographyHasTag(tags, 'late_champion')) return -999;
  entryTags.forEach(function(tag) {
    if (tag === 'default') score += 1;
    else if (biographyHasTag(tags, tag)) score += 5;
  });
  var conflicts = [
    ['champion','no_ring'],
    ['one_city','multi_city'],
    ['one_city','three_city'],
    ['early_peak','late_peak']
  ];
  conflicts.forEach(function(pair) {
    if (biographyHasTag(entryTags, pair[0]) && biographyHasTag(tags, pair[1])) score -= 8;
    if (biographyHasTag(entryTags, pair[1]) && biographyHasTag(tags, pair[0])) score -= 8;
  });
  return score;
}

function biographyTextsOverlap(a, b) {
  a = String(a || '');
  b = String(b || '');
  if (!a || !b) return false;
  var sentencesA = a.split(/[。！？；]/).map(function(s) { return s.trim(); }).filter(function(s) { return s.length >= 8; });
  var sentencesB = b.split(/[。！？；]/).map(function(s) { return s.trim(); }).filter(function(s) { return s.length >= 8; });
  for (var i = 0; i < sentencesA.length; i++) {
    for (var j = 0; j < sentencesB.length; j++) {
      if (sentencesA[i] === sentencesB[j]) return true;
      if (sentencesA[i].indexOf(sentencesB[j]) >= 0 || sentencesB[j].indexOf(sentencesA[i]) >= 0) return true;
    }
  }
  // 公共片段检测：覆盖“放进整段生涯看，”这类以逗号结尾、不构成完整句子的重复开头
  var short = a.length <= b.length ? a : b;
  var long = short === a ? b : a;
  var minLen = 8;
  for (var si = 0; si <= short.length - minLen; si++) {
    var frag = short.substr(si, minLen);
    if (long.indexOf(frag) >= 0) return true;
  }
  return false;
}

function biographyPickRule(section, tags, seed, salt, avoidTexts) {
  var list = CAREER_BIOGRAPHY_RULED_COPY[section] || CAREER_BIOGRAPHY_COPY[section] || [];
  if (!list.length) return '';
  var scored = list.map(function(entry, idx) {
    return { entry: entry, idx: idx, score: biographyEntryScore(entry, tags) };
  }).filter(function(item) { return item.score >= 0; });
  if (!scored.length) scored = list.map(function(entry, idx) { return { entry: entry, idx: idx, score: 0 }; });
  var best = Math.max.apply(null, scored.map(function(item) { return item.score; }));
  var pool = scored.filter(function(item) { return item.score >= best - 1; });
  var picked = pool[(seed + salt * 1103515245) % pool.length].entry;
  if (avoidTexts && avoidTexts.length) {
    for (var attempt = 0; attempt < pool.length; attempt++) {
      var candidateEntry = pool[(seed + salt * 1103515245 + attempt * 7919) % pool.length].entry;
      var candidateText = typeof candidateEntry === 'string' ? candidateEntry : (candidateEntry.text || '');
      var overlap = false;
      for (var ui = 0; ui < avoidTexts.length; ui++) {
        if (biographyTextsOverlap(candidateText, avoidTexts[ui])) { overlap = true; break; }
      }
      if (!overlap) { picked = candidateEntry; break; }
    }
  }
  return typeof picked === 'string' ? picked : (picked.text || '');
}

function buildCountPhrase(count, unit, label) {
  count = parseInt(count, 10) || 0;
  return count > 0 ? (count + unit + label) : '';
}

function joinPhraseParts(parts, fallback) {
  parts = (parts || []).filter(function(p) { return !!p; });
  if (!parts.length) return fallback || '';
  if (parts.length === 1) return parts[0];
  return parts.slice(0, -1).join('、') + '和' + parts[parts.length - 1];
}

var BIOGRAPHY_TEAM_CITIES = {
  ATL:'亚特兰大', BOS:'波士顿', BKN:'布鲁克林', CHA:'夏洛特', CHI:'芝加哥',
  CLE:'克利夫兰', DAL:'达拉斯', DEN:'丹佛', DET:'底特律', GSW:'金州',
  HOU:'休斯敦', IND:'印第安纳', LAC:'洛杉矶', LAL:'洛杉矶', MEM:'孟菲斯',
  MIA:'迈阿密', MIL:'密尔沃基', MIN:'明尼苏达', NOP:'新奥尔良', NYK:'纽约',
  OKC:'俄克拉荷马城', ORL:'奥兰多', PHI:'费城', PHX:'菲尼克斯', POR:'波特兰',
  SAC:'萨克拉门托', SAS:'圣安东尼奥', TOR:'多伦多', UTA:'犹他', WAS:'华盛顿'
};

function getBiographyTeamCity(team) {
  return BIOGRAPHY_TEAM_CITIES[team] || ((typeof getTeamName === 'function') ? getTeamName(team) : (team || '这座城市'));
}

function buildBiographyList(items) {
  items = (items || []).filter(function(x) { return !!x; });
  if (!items.length) return '';
  if (items.length === 1) return items[0];
  if (items.length === 2) return items[0] + '和' + items[1];
  return items.slice(0, -1).join('、') + '和' + items[items.length - 1];
}

function buildMultiCityLabel(cities) {
  var n = (cities || []).length;
  if (n <= 1) return cities[0] || '一座城市';
  if (n === 2) return '两座城市';
  if (n === 3) return '三座城市';
  if (n === 4) return '四座城市';
  return n + '座城市';
}

function buildBiographyFacts(r) {
  var s = STATE || {};
  var c = s.career || {};
  r = r || c.legacy || calculateLegacyResult();
  var seasons = (c.seasons || []).slice().sort(function(a, b) { return a.seasonNum - b.seasonNum; });
  var honors = c.honors || [];
  function cnt(key) { return honors.filter(function(h) { return (h.label || '').indexOf(key) >= 0 && !isRookieHonorForLaterSeason(h); }).length; }
  var teams = [];
  seasons.forEach(function(se) { if (teams.indexOf(se.team) < 0) teams.push(se.team); });
  if (!teams.length && s.careerTeam) teams.push(s.careerTeam);
  function tn(team) { return (typeof getTeamName === 'function') ? getTeamName(team) : (team || '一支球队'); }
  function city(team) { return getBiographyTeamCity(team); }
  var teamNames = teams.map(function(t) { return tn(t); });
  var cityNames = teams.map(function(t) { return city(t); });
  var ts = c.totalStats || {};
  var tg = Math.max(ts.games || 0, 1);
  var best = seasons[0] || {};
  seasons.forEach(function(se) {
    var score = (se.ovr || 0) + ((se.awards || []).length * 3) + ((se.wins || 0) * 0.08);
    var bestScore = (best.ovr || 0) + (((best.awards || []).length) * 3) + ((best.wins || 0) * 0.08);
    if (score > bestScore) best = se;
  });
  var championships = cnt('总冠军');
  var seasonChampTotal = 0;
  var champTeams = [];
  seasons.forEach(function(se) {
    if ((se.playoffResult || '').indexOf('总冠军') >= 0) {
      seasonChampTotal++;
      if (champTeams.indexOf(se.team) < 0) champTeams.push(se.team);
    }
  });
  if (seasonChampTotal > championships) championships = seasonChampTotal;
  var mvp = honors.filter(function(h) { return (h.label || '') === 'MVP'; }).length;
  var fmvp = cnt('总决赛MVP') + cnt('FMVP');
  var dpoy = cnt('DPOY');
  var allNBA = cnt('最佳阵容');
  var avgPts = (ts.pts || 0) / tg;
  var avgAst = (ts.ast || 0) / tg;
  var playerType = '球队基石';
  if (dpoy >= Math.max(1, mvp) && dpoy > 0) playerType = '防守图腾';
  else if (championships >= 3) playerType = '王朝基石';
  else if (avgPts >= 25) playerType = '得分机器';
  else if (avgAst >= 7) playerType = '组织核心';
  else if (championships === 0 && allNBA >= 3) playerType = '无冕英雄';
  else if (teams.length >= 3) playerType = '漂泊巨星';
  var shape = teams.length >= 3 ? '辗转多队' : (seasons.length >= 12 ? '巅峰漫长' : '慢慢长成');
  if ((c.currentAge || 0) >= 35 && (championships > 0 || mvp > 0)) shape = '老年封神';
  var bestHonor = (best.awards && best.awards.length) ? best.awards.map(function(a) { return a.label || a; }).join('、') : (best.playoffResult || '重要赛季');
  function seasonYear(n) { return 2025 + (parseInt(n, 10) || 1); }
  var coreHonor = joinPhraseParts([
    buildCountPhrase(championships, '座', '总冠军'),
    buildCountPhrase(mvp, '座', 'MVP'),
    buildCountPhrase(fmvp, '次', 'FMVP'),
    buildCountPhrase(dpoy, '次', 'DPOY'),
    buildCountPhrase(allNBA, '次', '最佳阵容'),
    buildCountPhrase(cnt('全明星'), '次', '全明星')
  ], '漫长而扎实的职业履历');
  var champLine = championships > 0 ? buildCountPhrase(championships, '枚', '总冠军戒指') : '';
  var defenseLine = dpoy > 0
    ? buildCountPhrase(dpoy, '次', '最佳防守球员')
    : ('场均' + ((ts.stl || 0) / tg).toFixed(1) + '次抢断、场均' + ((ts.blk || 0) / tg).toFixed(1) + '次盖帽的防守履历');
  var mvpLine = mvp > 0 ? buildCountPhrase(mvp, '座', 'MVP') : '';
  return {
    '姓名': (typeof getHupuDisplayName === 'function') ? getHupuDisplayName() : '我的球员',
    '英文名': '',
    '位置': (SIM_CONFIG && SIM_CONFIG.POSITIONS) ? (SIM_CONFIG.POSITIONS[s.position] || s.position) : (s.position || '球员'),
    '顺位': getDraftPickLabel(STATE.career && STATE.career.draft),
    '大学': '篮球世界',
    '选秀年': String((STATE.career && STATE.career.draft && STATE.career.draft.year) || 2026),
    '退役年龄': String(c.currentAge || 0),
    '首队': tn(teams[0] || s.careerTeam),
    '末队': tn(teams[teams.length - 1] || s.careerTeam),
    '最长球队': tn((r && r.longestTeam) || teams[0] || s.careerTeam),
    '球队1': tn(teams[0] || s.careerTeam),
    '球队2': tn(teams[1] || teams[0] || s.careerTeam),
    '球队3': tn(teams[2] || teams[teams.length - 1] || teams[0] || s.careerTeam),
    '球队列表': buildBiographyList(teamNames),
    '球队数': String(Math.max(teams.length, 1)),
    '城市1': city(teams[0] || s.careerTeam),
    '城市2': city(teams[1] || teams[0] || s.careerTeam),
    '城市3': city(teams[2] || teams[teams.length - 1] || teams[0] || s.careerTeam),
    '城市列表': buildBiographyList(cityNames),
    '冠军球队': champTeams.length ? tn(champTeams[0]) : '',
    '冠军城市': champTeams.length ? city(champTeams[0]) : '',
    '冠军球队列表': buildBiographyList(champTeams.map(function(t) { return tn(t); })),
    '冠军城市列表': buildBiographyList(champTeams.map(function(t) { return city(t); })),
    '多城称谓': buildMultiCityLabel(cityNames),
    '首尾线': teams.length > 1 ? ('从' + city(teams[0]) + '出发，最后在' + city(teams[teams.length - 1]) + '告别') : ('在' + city(teams[0] || s.careerTeam) + '度过整段旅程'),
    '赛季数': String(seasons.length || 0),
    '场次': String(ts.games || 0),
    '总得分': String(Math.round(ts.pts || 0)),
    '场均得分': ((ts.pts || 0) / tg).toFixed(1),
    '场均篮板': ((ts.reb || 0) / tg).toFixed(1),
    '场均助攻': ((ts.ast || 0) / tg).toFixed(1),
    '场均抢断': ((ts.stl || 0) / tg).toFixed(1),
    '场均盖帽': ((ts.blk || 0) / tg).toFixed(1),
    '总冠军': String(championships),
    'MVP': String(mvp),
    'FMVP': String(fmvp),
    'DPOY': String(dpoy),
    '最佳阵容': String(allNBA),
    '全明星': String(cnt('全明星')),
    '历史档位': (r && r.tier) || '优秀职业球员',
    '历史分': String((r && r.score) || 0),
    '最佳赛季': best.seasonNum ? (seasonYear(best.seasonNum) + '-' + String((seasonYear(best.seasonNum) + 1) % 100) + '赛季') : '某个重要赛季',
    '最高光球队': tn(best.team || teams[0] || s.careerTeam),
    '最高光年份': best.seasonNum ? String(seasonYear(best.seasonNum)) : '那一年',
    '最高光荣誉': bestHonor,
    '季后赛最佳成绩': best.playoffResult || '季后赛',
    '球员类型': playerType,
    '生涯曲线': shape,
    '核心荣誉': coreHonor,
    '冠军线': champLine || '那些接近山顶的赛季',
    '防守荣誉': defenseLine,
    'MVP线': mvpLine || '长期稳定的明星表现',
    '语气': '温暖'
  };
}

function getBiographySeasonsSorted() {
  var c = (STATE && STATE.career) || {};
  return (c.seasons || []).slice().sort(function(a, b) { return a.seasonNum - b.seasonNum; });
}

function getBiographyHonorCountsForSeasons(seasonNums) {
  var c = (STATE && STATE.career) || {};
  var map = {};
  seasonNums.forEach(function(n) { map[n] = true; });
  var counts = { championships:0, mvp:0, fmvp:0, dpoy:0, allNBA:0, allStar:0, roty:0 };
  var seasonChamp = 0;
  (c.seasons || []).forEach(function(se) {
    if (map[se.seasonNum] && (se.playoffResult || '').indexOf('总冠军') >= 0) seasonChamp++;
  });
  (c.honors || []).forEach(function(h) {
    if (!map[h.seasonNum] || isRookieHonorForLaterSeason(h)) return;
    var label = h.label || '';
    if (label.indexOf('总冠军') >= 0) counts.championships++;
    if (label === 'MVP') counts.mvp++;
    if (label.indexOf('总决赛MVP') >= 0 || label.indexOf('FMVP') >= 0) counts.fmvp++;
    if (label.indexOf('DPOY') >= 0) counts.dpoy++;
    if (label.indexOf('最佳阵容') >= 0) counts.allNBA++;
    if (label.indexOf('全明星') >= 0) counts.allStar++;
    if (label.indexOf('最佳新秀') >= 0) counts.roty++;
  });
  // 以赛季战绩为准：荣誉若因存档错位挂错队，用赛季自身结果纠正
  if (seasonChamp > 0) counts.championships = seasonChamp;
  return counts;
}

function buildEraHonorPhrase(counts) {
  return joinPhraseParts([
    buildCountPhrase(counts.championships, '座', '总冠军'),
    buildCountPhrase(counts.mvp, '座', 'MVP'),
    buildCountPhrase(counts.fmvp, '次', 'FMVP'),
    buildCountPhrase(counts.dpoy, '次', 'DPOY'),
    buildCountPhrase(counts.allNBA, '次', '最佳阵容'),
    buildCountPhrase(counts.allStar, '次', '全明星')
  ], '一段认真而扎实的岁月');
}

function classifyEraMeaning(era, facts, eraIndex, totalEras) {
  var tags = ['default'];
  if (era.years >= 6 && totalEras === 1) tags.push('one_city', 'loyalty');
  if (era.championships > 0) tags.push('champion');
  if (era.championships >= 2) tags.push('dynasty_builder');
  if (era.championships > 0 && era.years <= 3) tags.push('short_stay_legend');
  if (eraIndex === 0 && (era.championships > 0 || era.mvp > 0 || era.dpoy > 0)) tags.push('franchise_savior');
  if (eraIndex === totalEras - 1 && parseInt(facts['退役年龄'], 10) >= 34 && (era.championships > 0 || era.mvp > 0 || era.fmvp > 0 || era.dpoy > 0)) tags.push('late_career_gift');
  if (era.dpoy > 0 || (parseFloat(facts['场均抢断']) + parseFloat(facts['场均盖帽'])) >= 3.2) tags.push('defensive_identity');
  if (parseFloat(facts['场均得分']) >= 24 || era.mvp > 0) tags.push('offensive_system');
  if (era.championships === 0 && era.years >= 4 && (era.allNBA > 0 || era.allStar > 0)) tags.push('loyal_loser');
  if (era.championships === 0 && era.years <= 3 && totalEras > 1) tags.push('city_adopted_son');
  if (era.championships === 0 && era.mvp === 0 && era.dpoy === 0 && era.allNBA === 0 && era.years >= 2) tags.push('rebuild_anchor');
  return tags;
}

function analyzeTeamEras(facts) {
  var seasons = getBiographySeasonsSorted();
  var eras = [];
  var cur = null;
  seasons.forEach(function(se) {
    if (!cur || cur.team !== se.team) {
      if (cur) eras.push(cur);
      cur = { team: se.team, seasons: [], first: se.seasonNum, last: se.seasonNum };
    }
    cur.seasons.push(se);
    cur.last = se.seasonNum;
  });
  if (cur) eras.push(cur);
  function tn(team) { return (typeof getTeamName === 'function') ? getTeamName(team) : (team || '一支球队'); }
  function seasonYear(n) { return 2025 + (parseInt(n, 10) || 1); }
  eras.forEach(function(era, idx) {
    var nums = era.seasons.map(function(se) { return se.seasonNum; });
    var counts = getBiographyHonorCountsForSeasons(nums);
    Object.keys(counts).forEach(function(k) { era[k] = counts[k]; });
    era.years = era.seasons.length;
    era.teamName = tn(era.team);
    era.cityName = getBiographyTeamCity(era.team);
    era.range = era.first === era.last
      ? (seasonYear(era.first) + '-' + String((seasonYear(era.first) + 1) % 100))
      : (seasonYear(era.first) + '-' + String((seasonYear(era.last) + 1) % 100));
    era.honorPhrase = buildEraHonorPhrase(counts);
    era.tags = classifyEraMeaning(era, facts, idx, eras.length);
  });
  return eras;
}

function analyzeCareerNarrative(facts) {
  var tags = ['default'];
  function n(key) { return parseFloat(facts[key] || '0') || 0; }
  var teamCount = n('球队数');
  var seasons = n('赛季数');
  var championships = n('总冠军');
  var mvp = n('MVP');
  var fmvp = n('FMVP');
  var dpoy = n('DPOY');
  var allNBA = n('最佳阵容');
  var avgPts = n('场均得分');
  var avgAst = n('场均助攻');
  var avgDef = n('场均抢断') + n('场均盖帽');
  var age = n('退役年龄');
  var tier = facts['历史档位'] || '';
  if (teamCount <= 1) tags.push('one_city', 'loyalty');
  else tags.push('multi_city');
  if (teamCount === 2) tags.push('two_city');
  if (teamCount === 3) tags.push('three_city');
  if (teamCount === 4) tags.push('four_city');
  if (teamCount >= 5) tags.push('many_city');
  if (championships > 0) tags.push('champion');
  else tags.push('no_ring');
  if (championships >= 3) tags.push('dynasty');
  if (dpoy >= 2 || avgDef >= 3.2) tags.push('defender');
  if (avgPts >= 24 || mvp >= 1) tags.push('scorer');
  if (avgAst >= 6.5) tags.push('playmaker');
  var latePeak = false;
  var eras = analyzeTeamEras(facts);
  if (eras.length) {
    var lastEra = eras[eras.length - 1];
    latePeak = age >= 34 && !!lastEra && (lastEra.championships > 0 || lastEra.mvp > 0 || lastEra.fmvp > 0 || lastEra.dpoy > 0);
    if (age >= 34 && !!lastEra && lastEra.championships > 0) tags.push('late_champion');
  }
  if (latePeak) tags.push('late_peak');
  if (championships === 0 && (mvp > 0 || allNBA >= 3 || avgPts >= 23)) tags.push('regret_star');
  if (tier.indexOf('GOAT') >= 0 || tier.indexOf('历史前十') >= 0 || tier.indexOf('历史前二十') >= 0 || tier.indexOf('历史百大') >= 0) tags.push('top_legacy');
  if (seasons <= 4 && (mvp > 0 || dpoy > 0 || allNBA > 0 || championships > 0)) tags.push('early_peak');
  var primary = 'default';
  if (tags.indexOf('defender') >= 0) primary = 'defender';
  else if (tags.indexOf('playmaker') >= 0) primary = 'playmaker';
  else if (tags.indexOf('scorer') >= 0) primary = 'scorer';
  else if (tags.indexOf('champion') >= 0) primary = 'champion';
  var shape = 'balanced';
  if (tags.indexOf('one_city') >= 0) shape = 'one_city';
  else if (tags.indexOf('three_city') >= 0) shape = 'three_city';
  else if (tags.indexOf('multi_city') >= 0) shape = 'multi_city';
  if (tags.indexOf('regret_star') >= 0) shape = 'regret_star';
  return { tags: tags, primary: primary, shape: shape };
}

function buildEraBiographyTags(era, eraIndex, totalEras, careerTags) {
  var tags = ['default'];
  function add(tag) { if (tag && tags.indexOf(tag) < 0) tags.push(tag); }
  (era.tags || []).forEach(add);
  ['defender', 'scorer', 'playmaker', 'top_legacy'].forEach(function(tag) {
    if (biographyHasTag(careerTags, tag)) add(tag);
  });
  if ((era.championships || 0) > 0) add('champion');
  else add('no_ring');
  if ((era.championships || 0) >= 3) add('dynasty');
  if (eraIndex === totalEras - 1 && biographyHasTag(careerTags, 'late_peak')) add('late_peak');
  if (eraIndex === totalEras - 1 && biographyHasTag(careerTags, 'late_champion') && (era.championships || 0) > 0) add('late_champion');
  return tags;
}

function fillBiographyText(text, facts) {
  return String(text || '').replace(/\{([^{}]+)\}/g, function(m, key) {
    return Object.prototype.hasOwnProperty.call(facts, key) ? String(facts[key]) : m;
  });
}

function buildCareerBiographyText(r) {
  var facts = buildBiographyFacts(r);
  var narrative = analyzeCareerNarrative(facts);
  var eras = analyzeTeamEras(facts);
  var eraSig = eras.map(function(e) {
    return [e.team, e.years, e.championships, e.mvp, e.fmvp, e.dpoy, e.allNBA].join(':');
  }).join('|');
  var seed = biographySeed(facts['姓名'] + '|' + facts['赛季数'] + '|' + facts['总得分'] + '|' + facts['位置'] + '|' + facts['核心荣誉'] + '|' + eraSig);
  var paragraphs = [];
  var tags = narrative.tags;
  var usedTexts = [];
  var title = fillBiographyText(biographyPickRule('title', tags, seed, 1), facts);
  var leadText = biographyPickRule('lead', tags, seed, 2, usedTexts);
  paragraphs.push(fillBiographyText(leadText, facts));
  if (leadText) usedTexts.push(leadText);
  if (eras.length) {
    eras.forEach(function(era, idx) {
      var eraFacts = {};
      Object.keys(facts).forEach(function(k) { eraFacts[k] = facts[k]; });
      eraFacts['时代球队'] = era.teamName;
      eraFacts['时代城市'] = era.cityName;
      eraFacts['时代年份'] = String(era.years);
      eraFacts['时代范围'] = era.range;
      eraFacts['时代荣誉'] = era.honorPhrase;
      eraFacts['时代冠军'] = String(era.championships || 0);
      eraFacts['时代MVP'] = String(era.mvp || 0);
      eraFacts['时代DPOY'] = String(era.dpoy || 0);
      var eraTags = buildEraBiographyTags(era, idx, eras.length, tags);
      var eraText = biographyPickRule('era', eraTags, seed, 10 + idx, usedTexts);
      if (eraText) {
        paragraphs.push(fillBiographyText(eraText, eraFacts));
        usedTexts.push(eraText);
      }
    });
  } else {
    var firstCityText = biographyPickRule('first_city', tags, seed, 3, usedTexts);
    paragraphs.push(fillBiographyText(firstCityText, facts));
    if (firstCityText) usedTexts.push(firstCityText);
  }
  var plan = [];
  if (tags.indexOf('regret_star') >= 0 || tags.indexOf('no_ring') >= 0) {
    plan.push('low');
  }
  plan.push('core');
  if (tags.indexOf('multi_city') >= 0) plan.push('transfer');
  if (tags.indexOf('late_peak') >= 0) plan.push('late_peak');
  plan.push('city_memory', 'legacy');
  plan.forEach(function(section, idx) {
    var text = biographyPickRule(section, tags, seed, idx + 2, usedTexts);
    if (text) {
      paragraphs.push(fillBiographyText(text, facts));
      usedTexts.push(text);
    }
  });
  facts['传记标签'] = tags.join('、');
  return { title: title, body: paragraphs.join('\n\n'), facts: facts, narrative: narrative };
}

function wrapBiographyText(ctx, text, maxWidth, font) {
  ctx.font = font;
  return wrapCareerEvaluationText(text, maxWidth, ctx);
}

function wrapBiographyParagraphText(ctx, text, maxWidth, firstIndent, font) {
  ctx.font = font;
  var lines = [];
  var line = '';
  var noStart = '，。！？；、：,.!?;:）】」』”’…—';
  var noEnd = '“‘（【「『';
  var t = String(text || '');
  function lineWidth(s) { return ctx.measureText(s).width; }
  function currentMaxWidth() { return lines.length === 0 ? Math.max(40, maxWidth - firstIndent) : maxWidth; }
  for (var i = 0; i < t.length; i++) {
    var ch = t[i];
    var test = line + ch;
    if (line && lineWidth(test) > currentMaxWidth()) {
      if (noStart.indexOf(ch) >= 0) {
        line = test;
        continue;
      }
      if (noEnd.indexOf(line[line.length - 1]) >= 0) {
        line = test;
        continue;
      }
      lines.push(line);
      line = ch;
    } else {
      line = test;
    }
  }
  if (line) lines.push(line);
  return lines;
}

function generateCareerBiographyPosterDataURL(r) {
  var bio = buildCareerBiographyText(r);
  var C = {
    bg: '#ded6c9', paper: '#fffdf5', ink: '#14110e', ink2: '#40362f',
    muted: '#76695f', line: '#cdbda8', red: '#b82822',
    redSoft: 'rgba(184,40,34,0.10)', cream: '#f4e6d2',
    fd: '"Fredoka","Noto Sans SC",sans-serif',
    fb: '"Nunito","Noto Sans SC",sans-serif'
  };
  var W = 560, cx = W / 2, pad = 30, textW = W - pad * 2;
  var eras = analyzeTeamEras(bio.facts);
  var measureCtx = document.createElement('canvas').getContext('2d');
  var displayName = bio.facts['姓名'] || '我的球员';
  var subtitle = String(bio.title || '').replace(displayName, '').replace(/^[:：\s]+/, '').trim();
  if (!subtitle) subtitle = bio.facts['球员类型'] + ' · ' + bio.facts['生涯曲线'];
  var subtitleLines = wrapBiographyText(measureCtx, subtitle, textW - 26, '800 14px ' + C.fd).slice(0, 2);
  var bodyParts = bio.body.split(/\n{2,}/);

  var bodyFont = '500 11.2px ' + C.fb;
  var bodyLineH = 17;
  var paraGap = 11;
  var firstIndent = 12;
  var colGap = 24;
  var colW = (W - pad * 2 - colGap) / 2;
  var paraBlocks = bodyParts.map(function(p) {
    return wrapBiographyParagraphText(measureCtx, p, colW, firstIndent, bodyFont);
  });
  var totalColumnWeight = paraBlocks.reduce(function(sum, lines) { return sum + lines.length + 1; }, 0);
  var targetColumnWeight = totalColumnWeight / 2;
  var runningColumnWeight = 0;
  var splitIdx = paraBlocks.length;
  for (var pi = 0; pi < paraBlocks.length; pi++) {
    var pWeight = paraBlocks[pi].length + 1;
    if (pi > 0 && runningColumnWeight + pWeight > targetColumnWeight) {
      var beforeDiff = Math.abs(targetColumnWeight - runningColumnWeight);
      var afterDiff = Math.abs(targetColumnWeight - (runningColumnWeight + pWeight));
      splitIdx = afterDiff < beforeDiff ? pi + 1 : pi;
      break;
    }
    runningColumnWeight += pWeight;
  }
  if (splitIdx <= 0 || splitIdx >= paraBlocks.length) splitIdx = Math.ceil(paraBlocks.length / 2);
  var leftBlocks = paraBlocks.slice(0, splitIdx);
  var rightBlocks = paraBlocks.slice(splitIdx);
  if (!rightBlocks.length && leftBlocks.length > 1) {
    rightBlocks = leftBlocks.splice(Math.ceil(leftBlocks.length / 2));
  }
  function blocksHeight(blocks) {
    var h = 0;
    blocks.forEach(function(lines) { h += lines.length * bodyLineH + paraGap; });
    return h;
  }
  var routeItems = eras.map(function(era, idx) {
    return { no: idx + 1, range: era.range, team: era.teamName, code: era.team };
  });
  var routeH = routeItems.length ? 112 : 0;
  var quote = '“' + (bio.facts['多城称谓'] || '这段岁月') + '记住他的方式不总是宏大，而是那些被认真陪伴过的年份。”';
  var quoteFont = '900 14px ' + C.fd;
  var quoteInnerPad = 22;
  var quoteLineH = 20;
  var quoteLines = wrapBiographyText(measureCtx, quote, textW - quoteInnerPad * 2, quoteFont);
  if (quoteLines.length > 3) {
    quoteFont = '900 12.5px ' + C.fd;
    quoteLineH = 18;
    quoteLines = wrapBiographyText(measureCtx, quote, textW - quoteInnerPad * 2, quoteFont);
  }
  var quoteH = 30 + quoteLines.length * quoteLineH;
  var bodyH = Math.max(blocksHeight(leftBlocks), blocksHeight(rightBlocks));
  var H = Math.max(920, 274 + routeH + quoteH + bodyH + 92);

  var canvas = document.getElementById('posterCanvas');
  canvas.width = W * POSTER_SCALE;
  canvas.height = H * POSTER_SCALE;
  var ctx = canvas.getContext('2d');
  ctx.scale(POSTER_SCALE, POSTER_SCALE);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);

  ctx.save();
  ctx.fillStyle = C.paper;
  ctx.fillRect(12, 12, W - 24, H - 24);
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 2.2;
  ctx.strokeRect(12, 12, W - 24, H - 24);
  ctx.globalAlpha = 0.12;
  ctx.fillStyle = C.ink;
  for (var noiseY = 26; noiseY < H - 20; noiseY += 36) {
    for (var noiseX = 24; noiseX < W - 24; noiseX += 23) {
      if ((noiseX + noiseY) % 5 === 0) ctx.fillRect(noiseX, noiseY, 1, 1);
    }
  }
  ctx.restore();

  var y = 22;
  var mastY = y;
  ctx.fillStyle = C.ink;
  ctx.fillRect(pad, y, textW, 46);
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = C.paper;
  ctx.font = '900 25px ' + C.fd;
  ctx.fillText('BUILDPLAYER DAILY', pad + 14, y + 8);
  var logoSize = 22;
  var logoX = W - pad - logoSize - 10;
  var logoY = mastY + 11;
  ctx.font = '700 9px ' + C.fb;
  ctx.textAlign = 'right';
  ctx.fillText('RETIREMENT SPECIAL · CAREER FEATURE', logoX - 12, y + 18);
  ctx.textAlign = 'left';
  ctx.fillStyle = C.red;
  ctx.fillRect(pad, y + 43, textW, 3);

  if (_hupuLogo) {
    ctx.save();
    ctx.fillStyle = C.paper;
    ctx.fillRect(logoX - 4, logoY - 4, logoSize + 8, logoSize + 8);
    ctx.globalAlpha = 0.9;
    ctx.drawImage(_hupuLogo, logoX, logoY, logoSize, logoSize);
    ctx.restore();
  }
  y += 60;

  ctx.fillStyle = C.red;
  ctx.fillRect(pad, y, 8, 100);
  ctx.textAlign = 'left';
  ctx.fillStyle = C.ink;
  var titleSize = 54;
  measureCtx.font = '900 ' + titleSize + 'px ' + C.fd;
  while (measureCtx.measureText(displayName).width > textW - 34 && titleSize > 36) {
    titleSize -= 2;
    measureCtx.font = '900 ' + titleSize + 'px ' + C.fd;
  }
  ctx.font = '900 ' + titleSize + 'px ' + C.fd;
  ctx.fillText(displayName, pad + 20, y - 4);
  y += Math.max(50, titleSize - 2);
  ctx.fillStyle = C.ink2;
  ctx.font = '800 14px ' + C.fd;
  subtitleLines.forEach(function(line) {
    ctx.fillText(line, pad + 20, y);
    y += 18;
  });
  y += 10;
  ctx.fillStyle = C.cream;
  ctx.fillRect(pad + 20, y, textW - 20, 40);
  ctx.fillStyle = C.red;
  ctx.font = '700 10px ' + C.fb;
  ctx.fillText(bio.facts['赛季数'] + '年生涯 · ' + bio.facts['场次'] + '场 · ' + bio.facts['历史档位'], pad + 34, y + 6);
  ctx.fillStyle = C.ink2;
  ctx.font = '600 9px ' + C.fb;
  var routeText = bio.facts['球队列表'] || bio.facts['首队'];
  var routeTextLines = wrapBiographyText(measureCtx, routeText, textW - 70, '600 9px ' + C.fb).slice(0, 2);
  routeTextLines.forEach(function(line, idx) {
    ctx.fillText(line, pad + 34, y + 19 + idx * 11);
  });
  y += 56;

  if (routeItems.length) {
    ctx.fillStyle = C.red;
    ctx.fillRect(pad, y, 82, 20);
    ctx.fillStyle = C.ink;
    ctx.fillRect(pad + 82, y, textW - 82, 20);
    ctx.fillStyle = C.paper;
    ctx.font = '900 9px ' + C.fd;
    ctx.fillText('CAREER ROUTE', pad + 8, y + 5);
    y += 31;
    var itemGap = routeItems.length >= 9 ? 3 : 6;
    var itemW = (textW - itemGap * Math.max(0, routeItems.length - 1)) / routeItems.length;
    var logoSz = Math.max(13, Math.min(28, Math.floor(itemW * 0.34)));
    var teamFontSize = Math.max(6.2, Math.min(9.2, itemW / 7.2));
    var rangeFontSize = Math.max(5.8, Math.min(8, itemW / 8.3));
    routeItems.forEach(function(item, idx) {
      var x = pad + idx * (itemW + itemGap);
      var iy = y;
      ctx.fillStyle = idx % 2 === 0 ? C.paper : C.redSoft;
      ctx.fillRect(x, iy, itemW, 62);
      ctx.strokeStyle = C.line;
      ctx.lineWidth = 0.8;
      ctx.strokeRect(x, iy, itemW, 62);
      drawPosterTeamLogo(ctx, item.code, x + (itemW - logoSz) / 2, iy + 6, logoSz, C);
      ctx.fillStyle = C.ink;
      ctx.font = '900 ' + teamFontSize + 'px ' + C.fd;
      measureCtx.font = '900 ' + teamFontSize + 'px ' + C.fd;
      var teamLabel = item.team;
      while (teamLabel.length > 1 && measureCtx.measureText(teamLabel).width > itemW - 5) {
        teamLabel = teamLabel.slice(0, -1);
      }
      if (teamLabel !== item.team && teamLabel.length > 1) teamLabel = teamLabel.slice(0, -1) + '…';
      ctx.textAlign = 'center';
      ctx.fillText(teamLabel, x + itemW / 2, iy + logoSz + 17);
      ctx.fillStyle = C.muted;
      ctx.font = '700 ' + rangeFontSize + 'px ' + C.fb;
      ctx.fillText(item.range, x + itemW / 2, iy + logoSz + 28);
      ctx.textAlign = 'left';
    });
    y += 76;
  }

  ctx.fillStyle = C.ink;
  ctx.fillRect(pad, y, textW, 5);
  y += 12;
  ctx.fillStyle = C.redSoft;
  ctx.fillRect(pad, y, textW, quoteH);
  ctx.strokeStyle = C.red;
  ctx.lineWidth = 1.2;
  ctx.strokeRect(pad, y, textW, quoteH);
  ctx.fillStyle = C.red;
  ctx.fillRect(pad, y, 5, quoteH);
  ctx.textAlign = 'left';
  ctx.fillStyle = C.ink;
  ctx.font = quoteFont;
  quoteLines.forEach(function(line, idx) {
    ctx.fillText(line, pad + quoteInnerPad, y + 14 + idx * quoteLineH);
  });
  y += quoteH + 20;

  ctx.fillStyle = C.ink;
  ctx.font = '900 10px ' + C.fd;
  ctx.fillStyle = C.red;
  var featureBadgeW = 112;
  ctx.fillRect(pad, y - 1, featureBadgeW, 20);
  ctx.fillStyle = C.paper;
  ctx.fillText('FEATURE STORY', pad + 10, y + 4);
  ctx.strokeStyle = C.line;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(pad + featureBadgeW + 12, y + 9); ctx.lineTo(W - pad, y + 9); ctx.stroke();
  y += 28;

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  function drawBlocks(blocks, x, startY) {
    var yy = startY;
    ctx.fillStyle = C.ink;
    ctx.font = bodyFont;
    blocks.forEach(function(lines, blockIdx) {
      lines.forEach(function(line, lineIdx) {
        ctx.fillText(line, lineIdx === 0 ? x + firstIndent : x, yy);
        yy += bodyLineH;
      });
      yy += paraGap;
    });
    return yy;
  }
  var colY = y;
  drawBlocks(leftBlocks, pad, colY);
  drawBlocks(rightBlocks, pad + colW + colGap, colY);

  ctx.save();
  ctx.globalAlpha = 0.55;
  ctx.strokeStyle = C.line;
  ctx.beginPath();
  ctx.moveTo(cx, colY);
  ctx.lineTo(cx, H - 48);
  ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(pad, H - 42);
  ctx.lineTo(W - pad, H - 42);
  ctx.stroke();
  ctx.restore();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.fillStyle = C.muted;
  ctx.font = '400 9px ' + C.fb;
  ctx.fillText('我的完美建模球员  退役特刊报纸版', cx, H - 14);
  canvas._corsSafe = true;
  return canvas.toDataURL('image/png');
}

function generateCareerPoster() {
  trackEvent({act:"click",blk:"BMC098",pos:"TC9",label:"生成生涯海报"});
  updatePosterModeButtons();
  var s = STATE;
  var c = s.career || {};
  if (!c.totalStats && !s.finalOVR) { alert('请先完成生涯！'); return; }

  var ts = c.totalStats || {};
  var tg = Math.max(ts.games || 0, 1);
  var avg = {
    pts: +((ts.pts || 0) / tg).toFixed(1),
    reb: +((ts.reb || 0) / tg).toFixed(1),
    ast: +((ts.ast || 0) / tg).toFixed(1),
    stl: +((ts.stl || 0) / tg).toFixed(1),
    blk: +((ts.blk || 0) / tg).toFixed(1),
    tov: +((ts.tov || 0) / tg).toFixed(1)
  };
  var fga = ts.fga || 0, fgm = ts.fgm || 0;
  var fta = ts.fta || 0, ftm = ts.ftm || 0;
  var t3a = ts.threeA || 0, t3m = ts.threeM || 0;
  var pct = fga > 0 ? (fgm / fga * 100).toFixed(1) : '—';
  var ftPct = fta > 0 ? (ftm / fta * 100).toFixed(1) : '—';
  var threePct = t3a > 0 ? (t3m / t3a * 100).toFixed(1) : '—';

  var honors = c.honors || [];
  function cnt(key) { return honors.filter(function(h) { return (h.label || '').indexOf(key) >= 0 && !isRookieHonorForLaterSeason(h); }).length; }
  var championships = cnt('总冠军');
  var mvp = honors.filter(function(h) { return (h.label || '') === 'MVP'; }).length;
  var fmvp = cnt('总决赛MVP') + cnt('FMVP');
  var dpoy = cnt('DPOY');
  var allNBA = cnt('最佳阵容');
  var allStar = cnt('全明星');
  var roty = cnt('最佳新秀');

  var teamName = getTeamName ? getTeamName(s.careerTeam) : s.careerTeam;
  var allTeams = [];
  (c.seasons || []).forEach(function(se) {
    if (allTeams.indexOf(se.team) < 0) allTeams.push(se.team);
  });
  var allTeamsStr = allTeams.length ? allTeams.map(function(t) { return getTeamName ? getTeamName(t) : t; }).join('、') : teamName;
  var honorEntries = [];
  var champBySeason = {};
  (c.seasons || []).forEach(function(se) {
    if ((se.playoffResult || '').indexOf('总冠军') >= 0) champBySeason[se.seasonNum] = true;
  });
  (c.honors || []).forEach(function(h) {
    var label = h.label || '';
    if (label.indexOf('最佳新秀') >= 0) return; // 海报不显示最佳新秀/最佳新秀阵容
    if (label.indexOf('总冠军') >= 0 && !champBySeason[h.seasonNum]) return; // 与赛季战绩冲突的冠军荣誉忽略
    var hSeason = null;
    for (var hs2 = 0; hs2 < (c.seasons || []).length; hs2++) {
      if (c.seasons[hs2].seasonNum === h.seasonNum) { hSeason = c.seasons[hs2]; break; }
    }
    honorEntries.push({
      seasonNum: h.seasonNum || 1,
      team: hSeason && hSeason.team ? hSeason.team : s.careerTeam,
      label: label
    });
  });
  (c.seasons || []).forEach(function(se) {
    if (champBySeason[se.seasonNum]) {
      var hasChampEntry = honorEntries.some(function(he) { return he.seasonNum === se.seasonNum && (he.label || '').indexOf('总冠军') >= 0; });
      if (!hasChampEntry) honorEntries.push({ seasonNum: se.seasonNum, team: se.team, label: '🏆 总冠军' });
    }
  });
  honorEntries.sort(function(a, b) { return a.seasonNum - b.seasonNum; });
  function seasonYear(n) { return 2025 + (parseInt(n, 10) || 1); }
  function shortSeasonLabel(n) { var y = seasonYear(n); return y + '-' + String((y + 1) % 100); }
  // 按连续效力同一队的时代合并，一行展示该时代的全部荣誉
  var eraList = [];
  var eraTeam = null, eraFirst = 0, eraLast = 0;
  (c.seasons || []).slice().sort(function(a, b) { return a.seasonNum - b.seasonNum; }).forEach(function(se) {
    if (eraTeam === se.team) {
      eraLast = se.seasonNum;
    } else {
      if (eraTeam != null) eraList.push({ team: eraTeam, first: eraFirst, last: eraLast });
      eraTeam = se.team; eraFirst = se.seasonNum; eraLast = se.seasonNum;
    }
  });
  if (eraTeam != null) eraList.push({ team: eraTeam, first: eraFirst, last: eraLast });
  var seasonTeamMap = {};
  (c.seasons || []).forEach(function(se) { seasonTeamMap[se.seasonNum] = se.team; });
  var eraHonorMap = {};
  honorEntries.forEach(function(he) {
    var eTeam = seasonTeamMap[he.seasonNum] || he.team || s.careerTeam;
    var targetEra = null;
    for (var ei2 = 0; ei2 < eraList.length; ei2++) {
      if (eraList[ei2].team === eTeam && he.seasonNum >= eraList[ei2].first && he.seasonNum <= eraList[ei2].last) {
        targetEra = eraList[ei2]; break;
      }
    }
    if (!targetEra) {
      targetEra = { team: eTeam, first: he.seasonNum, last: he.seasonNum };
      eraList.push(targetEra);
      eraList.sort(function(a, b) { return a.first - b.first; });
    }
    var eIdx = eraList.indexOf(targetEra);
    if (!eraHonorMap[eIdx]) eraHonorMap[eIdx] = {};
    eraHonorMap[eIdx][he.label] = (eraHonorMap[eIdx][he.label] || 0) + 1;
  });
  var honorRows = [];
  eraList.forEach(function(er, eIdx) {
    var labels = Object.keys(eraHonorMap[eIdx] || {});
    var labelStr = labels.map(function(lb) {
      var n2 = eraHonorMap[eIdx][lb];
      return n2 > 1 ? lb + ' ×' + n2 : lb;
    }).join('、');
    var erTeamCn = getTeamName ? getTeamName(er.team) : er.team;
    var erRange = er.last > er.first ? seasonYear(er.first) + '-' + String(seasonYear(er.last) % 100) : shortSeasonLabel(er.first);
    honorRows.push(erRange + ' ' + erTeamCn + (labelStr ? ' ' + labelStr : ''));
  });
  if (!honorRows.length) honorRows.push('暂无主要荣誉');
  var honorCardH = 32 + honorRows.length * 20;

  var legacy = c.legacy || null;
  var retired = !!c.retired;
  var posName = (SIM_CONFIG && SIM_CONFIG.POSITIONS) ? SIM_CONFIG.POSITIONS[s.position] : s.position;
  var displayName = (typeof getHupuDisplayName === 'function') ? getHupuDisplayName() : '我的球员';

  var C = {
    bg: '#faf5eb', bgCard: '#fffaf2', border: '#f0e0cc',
    text: '#2d1f0e', textDim: '#8a7a66', textMuted: '#baa992',
    orange: '#ff6b35', gold: '#f7a600', green: '#2ec4b6', red: '#e63946',
    fd: '"Fredoka","Noto Sans SC",sans-serif',
    fb: '"Nunito","Noto Sans SC",sans-serif'
  };

  var W = 480, cardW = W - 28, cardX = 14, cx = W / 2;
  var evalText = pickCareerEvaluation();
  var measureCtx = document.createElement('canvas').getContext('2d');
  measureCtx.font = '500 11px ' + C.fb;
  var evalLines = wrapCareerEvaluationText(evalText, cardW - 28, measureCtx);
  var evalCardH = 38 + evalLines.length * 20;
  var sections = [80, 92, 126, 130, honorCardH, 104, evalCardH, 18];
  var H = sections.reduce(function(a, b) { return a + b + 6; }, 0) + 8;

  var canvas = document.getElementById('posterCanvas');
  canvas.width = W * POSTER_SCALE;
  canvas.height = H * POSTER_SCALE;
  var ctx = canvas.getContext('2d');
  ctx.scale(POSTER_SCALE, POSTER_SCALE);

  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);

  function card(x, y, w, h) {
    ctx.fillStyle = '#fffaf2';
    roundRectC(ctx, x, y, w, h, 12); ctx.fill();
    ctx.strokeStyle = '#f0e0cc';
    ctx.lineWidth = 1.2;
    roundRectC(ctx, x, y, w, h, 12); ctx.stroke();
  }

  function fillCell(x, y, w, h, r) {
    ctx.fillStyle = 'rgba(255,107,53,0.06)';
    roundRectC(ctx, x, y, w, h, r); ctx.fill();
  }

  var y = 0;

  // 1. header
  y = 16;
  if (_hupuLogo) {
    ctx.save();
    ctx.drawImage(_hupuLogo, W - 14 - 28, y - 4, 28, 28);
    ctx.restore();
  }
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '600 12px ' + C.fd;
  ctx.fillText('🏆 生涯海报', cx, y);
  y += 22;
  ctx.fillStyle = C.text;
  ctx.font = '800 30px ' + C.fd;
  ctx.fillText(displayName, cx, y);
  y += 34;

  // 2. 名片区
  var infoH = 92;
  card(cardX, y, cardW, infoH);
  var ix = cardX + 14, iw = cardW - 28;
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 12px ' + C.fd;
  ctx.fillText('👤 我的球员信息', ix, y + 8);

  function infoRow(label, val, yy) {
    ctx.fillStyle = C.textDim;
    ctx.font = '400 11px ' + C.fb;
    ctx.textAlign = 'left';
    ctx.fillText(label, ix, yy);
    ctx.fillStyle = C.text;
    ctx.font = '500 12px ' + C.fd;
    ctx.textAlign = 'right';
    ctx.fillText(val, ix + iw, yy);
  }
  infoRow('位置', posName, y + 30);
  infoRow('总评', String(s.finalOVR || 0), y + 50);
  infoRow('球队', allTeamsStr, y + 70);
  y += infoH + 6;

  // 3. 我的最后属性
  cardH = 126;
  card(cardX, y, cardW, cardH);
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 13px ' + C.fd;
  ctx.fillText('🏷️ 我的最后属性', cardX + 14, y + 8);

  var attrKeys2 = (SIM_CONFIG && SIM_CONFIG.ATTR_LIST) ? SIM_CONFIG.ATTR_LIST : [];
  var attrCN2 = (typeof window.attrCN === 'function') ? window.attrCN : function(k) { return k; };
  var aCols2 = 5, aGap2 = 3;
  var aW2 = (cardW - 32 - (aCols2 - 1) * aGap2) / aCols2, aH2 = 28;
  for (var ai2 = 0; ai2 < attrKeys2.length; ai2++) {
    var k2 = attrKeys2[ai2];
    var val2 = (s.attrs && s.attrs[k2] != null) ? s.attrs[k2] : 50;
    var grade2 = getGrade ? getGrade(val2) : { letter: 'C', color: C.textDim };
    var acol2 = ai2 % aCols2, arow2 = Math.floor(ai2 / aCols2);
    var ax2 = cardX + 14 + acol2 * (aW2 + aGap2);
    var ay2 = y + 28 + arow2 * (aH2 + aGap2);
    fillCell(ax2, ay2, aW2, aH2, 5);
    ctx.textAlign = 'center'; ctx.textBaseline = 'top';
    ctx.fillStyle = C.textDim;
    ctx.font = '400 8px ' + C.fb;
    ctx.fillText(attrCN2(k2), ax2 + aW2 / 2, ay2 + 2);
    ctx.fillStyle = grade2.color;
    ctx.font = '500 13px ' + C.fd;
    ctx.fillText(grade2.letter, ax2 + aW2 / 2, ay2 + 14);
  }
  y += cardH + 6;

  // 4. 生涯数据
  var cardH = 130;
  card(cardX, y, cardW, cardH);
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 13px ' + C.fd;
  ctx.fillText('📊 生涯总数据', cardX + 14, y + 8);

  var statLabels = ['总出场', '总得分', '场均得分', '场均篮板', '场均助攻', '场均抢断'];
  var statVals = [tg, Math.round(ts.pts || 0), avg.pts, avg.reb, avg.ast, avg.stl];
  var sCols = 3, sGap = 5;
  var sW = (cardW - 32 - (sCols - 1) * sGap) / sCols, sH = 34;
  for (var si = 0; si < 6; si++) {
    var scol = si % sCols, srow = Math.floor(si / sCols);
    var sx = cardX + 14 + scol * (sW + sGap);
    var sy = y + 30 + srow * (sH + sGap);
    fillCell(sx, sy, sW, sH, 6);
    ctx.textAlign = 'center'; ctx.textBaseline = 'top';
    ctx.fillStyle = C.text;
    ctx.font = '500 16px ' + C.fd;
    ctx.fillText(statVals[si].toString(), sx + sW / 2, sy + 2);
    ctx.fillStyle = C.textDim;
    ctx.font = '400 9px ' + C.fb;
    ctx.fillText(statLabels[si], sx + sW / 2, sy + 22);
  }
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.textDim;
  ctx.font = '400 10px ' + C.fb;
  ctx.fillText(fgm + '-' + fga + ' (' + pct + '%)、三分 ' + t3m + '-' + t3a + ' (' + threePct + '%)', cx, y + 30 + 2 * (sH + sGap) + 3);
  y += cardH + 6;

  // 5. 荣誉墙
  cardH = honorCardH;
  card(cardX, y, cardW, cardH);
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 13px ' + C.fd;
  ctx.fillText('🏆 生涯纪录', cardX + 14, y + 8);
  for (var hri = 0; hri < honorRows.length; hri++) {
    fillCell(cardX + 14, y + 26 + hri * 20, cardW - 28, 18, 5);
    ctx.fillStyle = C.text;
    ctx.font = '500 10px ' + C.fd;
    ctx.fillText(honorRows[hri], cardX + 18, y + 26 + hri * 20 + 3);
  }
  y += cardH + 6;

  // 6. 历史地位 / 最终模板摘要
  cardH = 104;
  card(cardX, y, cardW, cardH);
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 13px ' + C.fd;
  ctx.fillText(retired && legacy ? '🏅 历史地位' : '🏷️ 最终模板', cardX + 14, y + 8);
  if (retired && legacy) {
    ensureLegacyRankingDetails(legacy);
    infoRow('历史档位', legacy.tier || '—', y + 32);
    infoRow('名人堂', legacy.hof ? '✅ 入选' : '未入选', y + 54);
    infoRow('历史百大', (legacy.top100 ? '✅ 第' : '候选第') + legacy.historicalRank + '名', y + 76);
  } else {
    var archMatch = (typeof matchPlayerArchetype === 'function') ? matchPlayerArchetype(s.attrs, 1) : [];
    var archInfo = archMatch.length > 0 ? archMatch[0] : null;
    infoRow('总评', String(s.finalOVR || 0), y + 32);
    infoRow('风格', archInfo ? archInfo.cn : '无', y + 54);
    infoRow('位置', posName, y + 76);
  }
  y += cardH + 6;

  // 7. 生涯评价
  cardH = evalCardH;
  card(cardX, y, cardW, cardH);
  ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillStyle = C.orange;
  ctx.font = '500 13px ' + C.fd;
  ctx.fillText('💬 生涯评价', cardX + 14, y + 8);
  ctx.fillStyle = C.text;
  ctx.font = '500 11px ' + C.fb;
  for (var eli = 0; eli < evalLines.length; eli++) {
    ctx.fillText(evalLines[eli], cardX + 14, y + 30 + eli * 20);
  }
  y += cardH + 6;

  // 8. 水印
  ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
  ctx.fillStyle = C.textMuted;
  ctx.font = '400 9px ' + C.fb;
  ctx.fillText('我的完美建模球员  JRs出品', cx, H - 6);

  canvas._corsSafe = true;
  var dataURL = canvas.toDataURL('image/png');
  var pages = [dataURL];
  if (c.retired && c.legacy) {
    pages.push(generateRetirementStoryPosterDataURL(c.legacy));
  }
  if (c.retired && c.legacy) {
    pages.push(generateCareerBiographyPosterDataURL(c.legacy));
  }
  setPosterPages(pages, 0);
}

function stripPosterHtml(text) {
  return String(text || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function buildRetirementStoryPosterSections(r) {
  r = r || calculateLegacyResult();
  ensureLegacyRankingDetails(r);
  var c = STATE.career || {};
  var displayName = (typeof getHupuDisplayName === 'function') ? getHupuDisplayName() : '我的球员';
  var jerseyTeams = Array.isArray(r.jerseyTeams) ? r.jerseyTeams : [];
  var jerseyText = '';
  if (jerseyTeams.length) {
    var first = jerseyTeams[0];
    jerseyText = buildJerseyCeremonyCopy(first);
  } else {
    jerseyText = displayName + '离开球场时，没有球衣被升上屋顶。可有些号码不需要仪式确认，记住它的人会在多年后提起某个夜晚、某个回合、某次沉默的掌声。';
  }

  var mediaSections = ensureEndingMediaMoments(r).map(function(moment) {
    var story = ENDING_MEDIA_STORIES.find(function(item) { return item.id === moment.storyId; }) || ENDING_MEDIA_STORIES[0];
    var format = ENDING_MEDIA_FORMATS.find(function(item) { return item.id === moment.formatId; }) || ENDING_MEDIA_FORMATS[0];
    return {
      title: format.icon + ' ' + format.source,
      kicker: format.kicker,
      text: fillEndingMediaText(story.headline, r) + '\n\n' + fillEndingMediaText(story.body, r) + '\n\n“' + fillEndingMediaText(story.quote, r) + '”'
    };
  });

  var sections = [
    {
      title: '退役发言',
      kicker: 'Final Words',
      text: buildRetirementCopy(r)
    },
    {
      title: '退役球衣',
      kicker: 'Jersey Ceremony',
      text: jerseyText
    },
    {
      title: '名人堂',
      kicker: 'Hall of Fame',
      text: buildHofCopy(r)
    },
    {
      title: '历史百大',
      kicker: 'All-Time Top 100',
      text: buildTop100Copy(r) + '\n\n最终排名：第' + r.historicalRank + '名；历史分：' + r.score + '分；' + (r.top100 ? '正式入选NBA历史百大。' : '距离历史百大还差' + r.rankGapToTop100 + '位。')
    }
  ];
  sections.splice.apply(sections, [1, 0].concat(mediaSections));
  return sections.map(function(section) {
    section.text = stripPosterHtml(section.text);
    return section;
  });
}

function getRetirementPosterLines(ctx, text, maxW, font) {
  ctx.font = font;
  var rawLines = String(text || '').split('\n');
  var lines = [];
  for (var i = 0; i < rawLines.length; i++) {
    var piece = rawLines[i].trim();
    if (!piece) {
      if (lines.length && lines[lines.length - 1] !== '') lines.push('');
      continue;
    }
    var wrapped = wrapCareerEvaluationText(piece, maxW, ctx);
    for (var j = 0; j < wrapped.length; j++) lines.push(wrapped[j]);
  }
  return lines;
}

function drawRetirementPosterText(ctx, text, x, y, maxW, lineH, maxLines, font, color) {
  ctx.font = font;
  ctx.fillStyle = color;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  var lines = getRetirementPosterLines(ctx, text, maxW, font);
  if (maxLines && lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    lines[maxLines - 1] = lines[maxLines - 1].replace(/[，。！？；、,.!?;:]*$/, '') + '…';
  }
  for (var li = 0; li < lines.length; li++) {
    if (lines[li]) ctx.fillText(lines[li], x, y + li * lineH);
  }
}

function generateRetirementStoryPosterDataURL(r) {
  var c = STATE.career || {};
  r = r || c.legacy || calculateLegacyResult();
  if (!r) return '';

  var displayName = (typeof getHupuDisplayName === 'function') ? getHupuDisplayName() : '我的球员';
  var seasons = (c.seasons || []).length || (r.seasons || 0);
  var summary = seasons + '年生涯，' + Math.round(r.games || 0) + '场，' + Math.round(r.points || 0) + '分，' + (r.mvp || 0) + '座MVP，' + (r.championships || 0) + '枚总冠军戒指。';
  var C = {
    bg: '#faf5eb', bgCard: '#fffaf2', border: '#ead6bb',
    text: '#2d1f0e', textDim: '#7f6e59', textMuted: '#b49d80',
    orange: '#ff6b35', gold: '#d49a35', seal: '#b94835',
    fd: '"Fredoka","Noto Sans SC",sans-serif',
    fb: '"Nunito","Noto Sans SC",sans-serif'
  };
  var W = 480, cx = W / 2;
  var sections = buildRetirementStoryPosterSections(r);
  var gap = 12, headerH = 138, footerH = 38;
  var bodyFont = '500 11px ' + C.fb, bodyLineH = 20;
  var measureCtx = document.createElement('canvas').getContext('2d');
  var cardMetrics = sections.map(function(section, idx) {
    var cardW = idx % 2 === 0 ? 420 : 392;
    var lines = getRetirementPosterLines(measureCtx, section.text, cardW - 30, bodyFont);
    return { lines: lines, w: cardW, h: Math.max(136, 64 + Math.max(lines.length, 1) * bodyLineH) };
  });
  var H = headerH + footerH + (sections.length - 1) * gap;
  for (var mi = 0; mi < cardMetrics.length; mi++) H += cardMetrics[mi].h;
  H = Math.max(720, H);

  var canvas = document.getElementById('posterCanvas');
  canvas.width = W * POSTER_SCALE;
  canvas.height = H * POSTER_SCALE;
  var ctx = canvas.getContext('2d');
  ctx.scale(POSTER_SCALE, POSTER_SCALE);

  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);

  ctx.save();
  ctx.globalAlpha = 0.18;
  ctx.strokeStyle = C.border;
  ctx.lineWidth = 1;
  for (var gy = 94; gy < H; gy += 42) {
    ctx.beginPath();
    ctx.moveTo(24, gy);
    ctx.lineTo(W - 24, gy);
    ctx.stroke();
  }
  ctx.globalAlpha = 0.12;
  ctx.strokeStyle = C.gold;
  ctx.beginPath();
  ctx.arc(cx, 82, 126, Math.PI * 0.08, Math.PI * 0.92);
  ctx.stroke();
  ctx.restore();

  if (_hupuLogo) {
    ctx.save();
    ctx.drawImage(_hupuLogo, W - 42, 16, 28, 28);
    ctx.restore();
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = C.textMuted;
  ctx.font = '700 10px ' + C.fb;
  ctx.fillText('CAREER ARCHIVE', cx, 20);
  ctx.fillStyle = C.text;
  ctx.font = '900 34px ' + C.fd;
  ctx.fillText(displayName, cx, 42);

  ctx.fillStyle = C.bgCard;
  roundRectC(ctx, 34, 94, W - 68, 28, 14); ctx.fill();
  ctx.strokeStyle = C.border;
  ctx.lineWidth = 1;
  roundRectC(ctx, 34, 94, W - 68, 28, 14); ctx.stroke();
  ctx.fillStyle = C.textDim;
  ctx.font = '500 10px ' + C.fb;
  ctx.fillText('生涯小结：' + summary, cx, 102);

  var y = headerH;
  for (var si = 0; si < sections.length; si++) {
    var section = sections[si];
    var metric = cardMetrics[si];
    var cardH = metric.h;
    var cardW = metric.w;
    var cardX = si % 2 === 0 ? 18 : W - cardW - 18;
    var nodeX = si % 2 === 0 ? cardX + cardW + 11 : cardX - 11;

    ctx.save();
    ctx.globalAlpha = 0.72;
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(nodeX, y - 6);
    ctx.lineTo(nodeX, y + cardH + 6);
    ctx.stroke();
    ctx.fillStyle = C.bg;
    ctx.beginPath();
    ctx.arc(nodeX, y + 31, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = C.bgCard;
    roundRectC(ctx, cardX, y, cardW, cardH, 12); ctx.fill();
    ctx.strokeStyle = C.border;
    ctx.lineWidth = 1.2;
    roundRectC(ctx, cardX, y, cardW, cardH, 12); ctx.stroke();

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillStyle = C.orange;
    ctx.font = '800 14px ' + C.fd;
    ctx.fillText(section.title, cardX + 14, y + 12);
    ctx.fillStyle = C.textMuted;
    ctx.font = '700 8px ' + C.fb;
    ctx.textAlign = 'right';
    ctx.fillText(section.kicker.toUpperCase(), cardX + cardW - 14, y + 16);

    if (si === 0 || si === 3) {
      ctx.save();
      ctx.globalAlpha = 0.08;
      ctx.strokeStyle = C.seal;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(cardX + cardW - 44, y + cardH - 42, 28, 0, Math.PI * 2);
      ctx.stroke();
      ctx.font = '800 16px ' + C.fd;
      ctx.textAlign = 'center';
      ctx.fillStyle = C.seal;
      ctx.fillText(si === 0 ? '终章' : '史册', cardX + cardW - 44, y + cardH - 51);
      ctx.restore();
    }

    drawRetirementPosterText(ctx, section.text, cardX + 15, y + 44, cardW - 30, bodyLineH, null, bodyFont, C.text);
    y += cardH + gap;
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.fillStyle = C.textMuted;
  ctx.font = '400 9px ' + C.fb;
  ctx.fillText('我的完美建模球员  JRs出品', cx, H - 10);

  canvas._corsSafe = true;
  return canvas.toDataURL('image/png');
}

function generateRetirementStoryPoster() {
  var dataURL = generateRetirementStoryPosterDataURL();
  if (dataURL) setPosterPages([dataURL], 0);
}

// ── 关闭海报 ──
function closePoster() {
  document.getElementById('posterOverlay').style.display = 'none';
  if (STATE && STATE.career && STATE.career.retired) {
    if (STATE.career.flags && STATE.career.flags.postCareerDeferred) showCareerStats(1);
    else startPostCareerFlow();
  }
}

function getBranchEventById(id) {
  var source = getBranchEventSource();
  for (var i = 0; i < source.length; i++) {
    if (source[i].id === id) return source[i];
  }
  return null;
}

function startPostCareerFlow() {
  if (!STATE.career || !STATE.career.retired) return;
  STATE.career.flags = STATE.career.flags || {};
  STATE._postCareerScenePage = 0;
  STATE._postCareerEvent = null;
  if (getBranchNode('post_career') === 'start' && !STATE.career.flags.postCareerDone) {
    askSimulateFirstSummer();
    return;
  }
  showNextPostCareerEvent();
}

function askSimulateFirstSummer() {
  var existing = document.getElementById('first-summer-modal');
  if (existing) existing.remove();
  var html = '<div class="team-picker-overlay" id="first-summer-modal">';
  html += '<div class="team-picker-modal">';
  html += '<div class="team-picker-header"><span>🏁 退役后的第一个夏天</span></div>';
  html += '<div style="padding:14px;">';
  html += '<div style="font-size:13px;color:var(--text-dim);line-height:1.65;margin-bottom:14px;">你从更衣室搬出行李，站在停车场里，第一次不知道明天该去哪个球馆。手机响了一整天，大家都在问你接下来想做什么。<br><br>要模拟这段退役后的夏天吗？</div>';
  html += '<button class="btn btn-primary btn-sm" style="width:100%;margin-bottom:8px;" onclick="confirmStartPostCareer()">开始模拟</button>';
  html += '<button class="btn btn-secondary btn-sm" style="width:100%;" onclick="declinePostCareerForNow()">暂不模拟</button>';
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function confirmStartPostCareer() {
  var modal = document.getElementById('first-summer-modal');
  if (modal) modal.remove();
  STATE.career.flags = STATE.career.flags || {};
  STATE.career.flags.postCareerDeferred = false;
  showNextPostCareerEvent();
}

function declinePostCareerForNow() {
  var modal = document.getElementById('first-summer-modal');
  if (modal) modal.remove();
  STATE.career.flags = STATE.career.flags || {};
  STATE.career.flags.postCareerDeferred = true;
  showCareerStats(1);
}

function showNextPostCareerEvent() {
  var node = getBranchNode('post_career');
  var id = '';
  if (node === 'start') id = 'post_career_opening';
  else if (node === 'gap_year') id = 'post_career_gap_return';
  else if (node === 'post_career_map') id = 'post_career_map';
  else if (node === 'commentator' || node === 'assistant_coach' || node === 'head_coach' || node === 'team_owner' || node === 'youth_academy' || node === 'china_consultant' || node === 'agency_partner' || node === 'freelancer') id = 'post_career_first_year';
  else if (node === 'low_key' || node === 'identity_settled' || node === 'identity_adjusted' || node === 'identity_voice') {
    finishPostCareer();
    return;
  }
  var ev = id ? getBranchEventById(id) : null;
  if (!ev || hasCareerEventBeenSeen(ev, STATE.career)) { finishPostCareer(); return; }
  STATE._postCareerEvent = ev;
  STATE._postCareerScenePage = 0;
  showPostCareerEventModal(ev);
}

function showPostCareerEventModal(ev) {
  var existing = document.getElementById('post-career-modal');
  if (existing) existing.remove();
  var scenes = ev.scenes || [];
  var sceneIdx = STATE._postCareerScenePage || 0;
  var title = getPlayerFacingBranchTitle(ev.title);
  var html = '<div class="team-picker-overlay" id="post-career-modal">';
  html += '<div class="team-picker-modal">';
  html += '<div class="team-picker-header"><span>' + title + '</span></div>';
  html += '<div style="padding:14px 14px 8px;">';
  if (scenes.length && sceneIdx < scenes.length) {
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">剧情</div>';
    html += '<div style="font-size:13px;color:var(--text-dim);line-height:1.65;margin-bottom:14px;">' + fillBranchEventText(scenes[sceneIdx]) + '</div>';
    html += '<button class="btn btn-primary btn-sm" style="width:100%;" onclick="continuePostCareerScene()">继续</button>';
  } else {
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">重点</div>';
    html += '<div style="font-size:13px;color:var(--text-dim);line-height:1.55;margin-bottom:12px;">' + sanitizePlayerFacingText(fillBranchEventText(ev.body)) + '</div>';
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">选择</div>';
    ev.choices.forEach(function(ch, ci) {
      var locked = isBranchChoiceLocked(ch);
      var lockHint = locked ? (ch.lockHint || '需要对应线路结果') : '';
      var btnStyle = 'width:100%;margin-bottom:8px;justify-content:flex-start;text-align:left;' + (locked ? 'opacity:.45;cursor:not-allowed;' : '');
      var onclick = locked ? '' : 'onclick="choosePostCareerEvent(' + ci + ')"';
      html += '<button class="btn btn-secondary btn-sm" style="' + btnStyle + '" ' + onclick + (locked ? ' disabled' : '') + '>' + ch.label + '<span style="display:block;font-size:11px;font-family:var(--font-body);font-weight:400;opacity:.75;margin-left:4px;">' + sanitizePlayerFacingText(fillBranchEventText(locked ? lockHint : getEventChoicePrediction(ch, ev, ci))) + '</span></button>';
    });
  }
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function continuePostCareerScene() {
  var ev = STATE._postCareerEvent;
  if (!ev) return;
  STATE._postCareerScenePage = (STATE._postCareerScenePage || 0) + 1;
  showPostCareerEventModal(ev);
}

function choosePostCareerEvent(choiceIdx) {
  var ev = STATE._postCareerEvent;
  if (!ev) return;
  var ch = ev.choices[choiceIdx];
  if (!ch || isBranchChoiceLocked(ch)) return;
  var beforeAttributes = captureEventAttributeSnapshot();
  var msg = ch.apply ? ch.apply() : '';
  msg = applyChoiceBonus(ch, msg);
  recordBranchChoice(ev, ch, msg, 'post_career');
  var modal = document.getElementById('post-career-modal');
  if (modal) modal.remove();
  STATE._postCareerEvent = null;
  STATE._postCareerScenePage = 0;
  showPostCareerResultModal(ev.title, msg, diffEventAttributeSnapshot(beforeAttributes));
}

function showPostCareerResultModal(title, msg, attributeChanges) {
  var existing = document.getElementById('post-career-result-modal');
  if (existing) existing.remove();
  var html = '<div class="team-picker-overlay" id="post-career-result-modal">';
  html += '<div class="team-picker-modal">';
  html += '<div class="team-picker-header"><span>' + getPlayerFacingBranchTitle(title) + '</span></div>';
  html += '<div class="event-result-body">';
  html += formatBranchResultText(fillBranchEventText(msg));
  html += renderEventAttributeChanges(attributeChanges);
  html += '<button class="btn btn-primary btn-sm" style="width:100%;" onclick="finishPostCareerStep()">继续</button>';
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function finishPostCareerStep() {
  var modal = document.getElementById('post-career-result-modal');
  if (modal) modal.remove();
  showNextPostCareerEvent();
}

function applyPostCareerIdentityDelta(amount) {
  var id = (STATE.career.flags && STATE.career.flags.postCareerIdentity) || 'commentator';
  var key = 'mediaTrust';
  if (id === 'assistant_coach' || id === 'head_coach') key = 'lockerRoomTrust';
  else if (id === 'team_owner' || id === 'agency_partner') key = 'businessValue';
  else if (id === 'china_consultant') key = 'chinaPopularity';
  else if (id === 'youth_academy') key = 'fanSupport';
  else if (id === 'freelancer') key = 'mediaTrust';
  addProfileDelta(key, amount || 2);
}

function finishPostCareer() {
  STATE.career.flags = STATE.career.flags || {};
  STATE.career.flags.postCareerDone = true;
  archiveCompletedCareer();
  clearAutoSaveStorage();
  showCareerStats(1);
}

var _countdownLegacyEvent = null;
var _countdownLegacyScenePage = 0;

function startCountdownLegacyFlow() {
  var ev = getBranchEventById('countdown_legacy');
  if (!ev || hasCareerEventBeenSeen(ev, STATE.career)) { showPlayerRetirementChoice(); return; }
  _countdownLegacyEvent = ev;
  _countdownLegacyScenePage = 0;
  showCountdownLegacyModal();
}

function showCountdownLegacyModal() {
  var ev = _countdownLegacyEvent;
  if (!ev) return;
  var existing = document.getElementById('countdown-legacy-modal');
  if (existing) existing.remove();
  var scenes = ev.scenes || [];
  var sceneIdx = _countdownLegacyScenePage || 0;
  var title = getPlayerFacingBranchTitle(ev.title);
  var html = '<div class="team-picker-overlay" id="countdown-legacy-modal">';
  html += '<div class="team-picker-modal">';
  html += '<div class="team-picker-header"><span>' + title + '</span></div>';
  html += '<div style="padding:14px 14px 8px;">';
  if (scenes.length && sceneIdx < scenes.length) {
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">剧情</div>';
    html += '<div style="font-size:13px;color:var(--text-dim);line-height:1.65;margin-bottom:14px;">' + fillBranchEventText(scenes[sceneIdx]) + '</div>';
    html += '<button class="btn btn-primary btn-sm" style="width:100%;" onclick="continueCountdownLegacyScene()">继续</button>';
  } else {
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">重点</div>';
    html += '<div style="font-size:13px;color:var(--text-dim);line-height:1.55;margin-bottom:12px;">' + sanitizePlayerFacingText(fillBranchEventText(ev.body)) + '</div>';
    html += '<div style="font-size:11px;color:var(--orange);font-weight:700;margin-bottom:6px;">选择</div>';
    ev.choices.forEach(function(ch, ci) {
      var locked = isBranchChoiceLocked(ch);
      var lockHint = locked ? (ch.lockHint || '需要对应线路结果') : '';
      var btnStyle = 'width:100%;margin-bottom:8px;justify-content:flex-start;text-align:left;' + (locked ? 'opacity:.45;cursor:not-allowed;' : '');
      var onclick = locked ? '' : 'onclick="chooseCountdownLegacyEvent(' + ci + ')"';
      html += '<button class="btn btn-secondary btn-sm" style="' + btnStyle + '" ' + onclick + (locked ? ' disabled' : '') + '>' + ch.label + '<span style="display:block;font-size:11px;font-family:var(--font-body);font-weight:400;opacity:.75;margin-left:4px;">' + sanitizePlayerFacingText(fillBranchEventText(locked ? lockHint : getEventChoicePrediction(ch, ev, ci))) + '</span></button>';
    });
  }
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function continueCountdownLegacyScene() {
  var ev = _countdownLegacyEvent;
  if (!ev) return;
  _countdownLegacyScenePage = (_countdownLegacyScenePage || 0) + 1;
  showCountdownLegacyModal();
}

function chooseCountdownLegacyEvent(choiceIdx) {
  var ev = _countdownLegacyEvent;
  if (!ev) return;
  var ch = ev.choices[choiceIdx];
  if (!ch || isBranchChoiceLocked(ch)) return;
  var beforeAttributes = captureEventAttributeSnapshot();
  var msg = ch.apply ? ch.apply() : '';
  msg = applyChoiceBonus(ch, msg);
  recordBranchChoice(ev, ch, msg, 'countdown');
  var modal = document.getElementById('countdown-legacy-modal');
  if (modal) modal.remove();
  _countdownLegacyEvent = null;
  _countdownLegacyScenePage = 0;
  showCountdownLegacyResultModal(ev.title, msg, diffEventAttributeSnapshot(beforeAttributes));
}

function showCountdownLegacyResultModal(title, msg, attributeChanges) {
  var existing = document.getElementById('countdown-legacy-result-modal');
  if (existing) existing.remove();
  var html = '<div class="team-picker-overlay" id="countdown-legacy-result-modal">';
  html += '<div class="team-picker-modal">';
  html += '<div class="team-picker-header"><span>' + getPlayerFacingBranchTitle(title) + '</span></div>';
  html += '<div class="event-result-body">';
  html += formatBranchResultText(fillBranchEventText(msg));
  html += renderEventAttributeChanges(attributeChanges);
  html += '<button class="btn btn-primary btn-sm" style="width:100%;" onclick="finishCountdownLegacy()">继续</button>';
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function finishCountdownLegacy() {
  var modal = document.getElementById('countdown-legacy-result-modal');
  if (modal) modal.remove();
  STATE._retirementOfferPhase = 'pre-training';
  showPlayerRetirementChoice();
}

window.PERFECT_PLAYER_CAREER_BALANCE = {
  version: '2026-08-age-attribute-v2',
  maxPlayableAge: PLAYER_CAREER_MAX_AGE,
  agingUsesAgeAndAttribute: true,
  maintenanceMaxReductionPerAttribute: 1,
  retirementUsesAgeAndAbility: true,
  trainingPointCosts: { below85:1, from85:2, from90:3, from95:5, from98:7 }
};

